css:
.section_services{position:relative}
.ab_light-bg{position:absolute;top:0;right:0;bottom:0;left:0;z-index:-1;overflow-x:hidden;overflow-y:hidden;pointer-events:none;background-image:radial-gradient(ellipse at 30% 25%,#FFFDF8,#F2F0EA 60%)}
.ab_light-glow{position:absolute;left:0;right:0;z-index:-2;height:220px;pointer-events:none}
.ab_light-glow.is-top{top:-150px;background-image:radial-gradient(60% 100% at 50% 100%,rgba(255,190,140,0.42),transparent 72%)}
.ab_light-glow.is-bottom{bottom:-150px;background-image:radial-gradient(60% 100% at 50% 0%,rgba(160,190,255,0.28),transparent 72%)}
.ab_services_orbit-art{position:absolute;right:3vw;top:clamp(60px,8vw,120px);z-index:1;width:clamp(240px,30vw,420px);height:auto;opacity:0.8;pointer-events:none}
.ab_planet.is-services{width:clamp(70px,8vw,120px);right:6vw;top:40px}
.ab_bento_grid{position:relative;z-index:3;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));grid-auto-rows:minmax(230px,auto);grid-auto-flow:row dense;grid-row-gap:16px;grid-column-gap:16px;padding-top:28px}
.ab_bento_cell{display:flex;grid-column:span 2}
.ab_bento_cell.is-xl{grid-column:span 4;grid-row:span 2}
.ab_bento_cell.is-tall{grid-row:span 2}
.ab_bento-card{position:relative;display:flex;flex-direction:column;flex-grow:1;flex-shrink:1;flex-basis:0%;grid-row-gap:14px;grid-column-gap:14px;padding-top:22px;padding-right:22px;padding-bottom:22px;padding-left:22px;background-color:var(--_color---neutral--deep);border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair);color:var(--_color---text--primary);transition:background-color 300ms ease,border-color 300ms ease,box-shadow 400ms ease}
.ab_bento-card:hover{z-index:10;background-color:var(--_color---neutral--panel);border-top-color:transparent;border-right-color:transparent;border-bottom-color:transparent;border-left-color:transparent;box-shadow:0 24px 50px -24px rgba(11,12,20,0.3)}
.ab_bento-card.is-planet{padding-top:0;padding-right:0;padding-bottom:0;padding-left:0;background-color:#05060A;border-top-color:transparent;border-right-color:transparent;border-bottom-color:transparent;border-left-color:transparent}
.ab_bento-card_viz{position:relative;z-index:1;flex-grow:1;flex-shrink:1;flex-basis:0%;min-height:130px;overflow-x:hidden;overflow-y:hidden;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair);background-color:var(--_color---neutral--void)}
.ab_bento-card_viz.is-planet{min-height:360px;border-top-style:none;border-right-style:none;border-bottom-style:none;border-left-style:none;background-color:#05060A;background-image:radial-gradient(ellipse at 60% 40%,rgba(124,92,255,0.28),transparent 60%)}
.ab_bento-card_copy{position:relative;z-index:1;display:flex;flex-direction:column;grid-row-gap:8px;grid-column-gap:8px;padding-right:40px}
.ab_bento-card_label{color:var(--_color---text--tertiary)}
.ab_bento-card_title{margin-top:0;margin-bottom:0;font-weight:800;font-stretch:112%;font-size:clamp(20px,1.7vw,24px);line-height:1.05;text-transform:uppercase}
.ab_bento-card_text{max-width:48ch;font-size:15px;line-height:1.55;color:var(--_color---text--secondary)}
.ab_bento-card_tools{color:var(--_color---text--tertiary)}
.ab_bento-card_link{position:absolute;right:14px;bottom:14px;z-index:6;display:grid;align-items:center;justify-items:center;width:36px;height:36px;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair-strong);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair-strong);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair-strong);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair-strong);color:var(--_color---text--primary);font-size:15px;text-decoration:none;transition:background-color 250ms ease,color 250ms ease,border-color 250ms ease,transform 300ms ease}
.ab_bento-card_link:hover{background-color:var(--_color---brand--signal);border-top-color:var(--_color---brand--signal);border-right-color:var(--_color---brand--signal);border-bottom-color:var(--_color---brand--signal);border-left-color:var(--_color---brand--signal);color:var(--_color---brand--on-signal);transform:rotate(45deg)}
.ab_sr-only{position:absolute;width:1px;height:1px;overflow-x:hidden;overflow-y:hidden;white-space:nowrap;clip:rect(0 0 0 0)}
.ab_services_cta{position:relative;z-index:3;display:flex;flex-wrap:wrap;align-items:center;grid-row-gap:14px;grid-column-gap:14px;margin-top:48px}
.ab_services_cta-note{margin-left:auto;color:var(--_color---text--tertiary)}
@media screen and (max-width: 991px) {
.ab_bento_grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.ab_bento_cell{grid-column:span 1;grid-row:span 1}
.ab_bento_cell.is-xl{grid-column:span 2;grid-row:span 1}
.ab_bento_cell.is-tall{grid-row:span 1}
.ab_bento-card_viz{min-height:190px}
}
@media screen and (max-width: 767px) {
.ab_services_orbit-art{display:none}
}
@media screen and (max-width: 479px) {
.ab_bento_grid{grid-template-columns:minmax(0,1fr)}
.ab_bento_cell.is-xl{grid-column:span 1}
.ab_services_cta-note{margin-left:0}
}
